import sys

def minChar(S: str) -> int:
    if not S:
        return 0
    rev_S = S[::-1]
    combined = S + '#' + rev_S
    n = len(combined)
    lps = [0] * n
    length = 0
    i = 1
    while i < n:
        if combined[i] == combined[length]:
            length += 1
            lps[i] = length
            i += 1
        else:
            if length != 0:
                length = lps[length - 1]
            else:
                lps[i] = 0
                i += 1
    longest_palindrome_prefix_len = lps[-1]
    return len(S) - longest_palindrome_prefix_len

def main():
    s = sys.stdin.read().strip()
    result = minChar(s)
    print(result)

if __name__ == "__main__":
    main()
